      prismP(B.p({c:'#3a3f43', glow:'#ffe0b4', gk:0.45}), Pin, y0, yb, true);
      mullP(B.p(RED), P, y0, yb, 4.7, 1.7, 0.0, 1.0);
      bandsP(B.p(RED), P, y0, yb, 4.7, 1.7, 0.05);
      { const o = B.p(RED2); for (let i = 0; i < P.length; i++){ const a = P[i], b = P[(i+1) % P.length], L = Math.hypot(b[0]-a[0], b[1]-a[1]), n2 = Math.max(2, Math.round(L/9.4));
          for (let j = 0; j < n2; j++){ const t0 = j/n2, t1 = (j+1)/n2, p0 = [a[0] + (b[0]-a[0])*t0, a[1] + (b[1]-a[1])*t0], p1 = [a[0] + (b[0]-a[0])*t1, a[1] + (b[1]-a[1])*t1];
            for (let f = 0; f < 4; f++){ const ya = y0 + (yb - y0)*f/4, yb2 = y0 + (yb - y0)*(f+1)/4; segP(o, [p0[0], ya, p0[1]], [p1[0], yb2, p1[1]], 0.5, 4); segP(o, [p1[0], ya, p1[1]], [p0[0], yb2, p0[1]], 0.5, 4); } } } }
      prismP(B.p(RED), P, yb - 0.9, yb + 0.6, false, true);
      // the glass shafts
      piece(B, P, yb + 0.6, ym0, {g:GL, m:'#a89c8c', sp:1.9, mw:0.16, b:'#8a7f72', fh:3.75, bh:0.3});
      piece(B, P, ym1, yt0, {g:GL, m:'#a89c8c', sp:1.9, mw:0.16, b:'#8a7f72', fh:3.75, bh:0.3});
      // red bands with rectangular openings
      for (const [a0, a1] of [[ym0, ym1], [yt0 - 3.9, yt1]]){
        prismP(B.p(RED), offP(P, -0.35), a0, a1, false, true);
        winsP(B.p(DK), offP(P, -0.35), a0 + (a1 - a0)*0.32, a1 - 0.8, a1 - a0, 4.7, 2.2, (a1 - a0)*0.36, 0.06);
      }
