// COSCO Tower (Grand Millennium Plaza, 1998; 228 m, 53 floors - Wikipedia; the OSM part gives the 220 m roof): dark blue-grey glass
// with a light vertical spine down the middle of each long face and silver corner strips; the pitched crown (light stone frames
// round a glazed gable, a pyramid roof behind) carries the company's letters on its harbour face (sign layer).
LANDMARKS.hkvcosco = {zh:'中远大厦', en:'COSCO Tower', cat:'new', r:42, h:228,
  lt:{m:1, c:'#ffe0b4', k:0.65},
  build(){
    const k = 'hkvcosco', P = clean(FD[k].t), X = mk(k, P), g = X.g, B = X.B, gf = X.gr, c = cenP(P), R = rectOf(P);
    const GL = {c:'#43566a', m:1, fh:3.9, cw:3.0}, STN = {c:'#d9c3ad', m:0, lc:'#ffe9d0', lk:1.1};
    foot(B, P, gf, 0.3, 9);
    piece(B, P, 9, 204, {g:GL, m:'#8e9aa6', sp:1.6, mw:0.12, b:'#2f3c49', fh:3.9, bh:0.5});
    // light vertical spine on the two long faces (the stair / core band seen from the harbour)
    for (const sv of [-1, 1]){ const f = R.f, hw = R.hw; const a = f.w(-4, sv*(hw + 0.15)), b = f.w(4, sv*(hw + 0.15)); quadP(B.p('#aeb7bf'), [a[0], 9, a[1]], [b[0], 9, b[1]], [b[0], 204, b[1]], [a[0], 204, a[1]]); }
    edgeP(B.p('#c7ccd0'), P, 204, 0.5, 1.2, 0.08);
    // crown: inset stone frame storey, then a pitched roof whose gables face the long sides
    const f = R.f, u0 = R.u0 + 3, u1 = R.u1 - 3, hw = R.hw - 3;
    prismP(B.p(STN), rectP(f, u0, u1, -hw, hw), 204, 210);
    const ridge = 228, yE = 210, gab = B.p(STN), gl = B.p({c:'#566b80', glow:'#cfe3ff', gk:0.35});
    const A = f.p(u0, yE, -hw), Bq = f.p(u1, yE, -hw), Cq = f.p(u1, yE, hw), Dq = f.p(u0, yE, hw), R0 = f.p(u0 + 4, ridge, 0), R1 = f.p(u1 - 4, ridge, 0);
    quadP(gab, A, Bq, R1, R0); quadP(gab, Cq, Dq, R0, R1); triP(gl, Bq, Cq, R1); triP(gl, Dq, A, R0);
    // stone frames on the gable faces
    for (const s of [-1, 1]){ const P0 = f.p(s < 0 ? u0 : u1, yE, -hw), P1 = f.p(s < 0 ? u0 : u1, yE, hw), Rt = s < 0 ? R0 : R1; segP(gab, P0, Rt, 0.7, 4); segP(gab, P1, Rt, 0.7, 4); }
    segP(gab, R0, R1, 0.6, 4);
    LCylD(g, 0.35, 0.6, 8, (R0[0] + R1[0])/2, ridge, (R0[2] + R1[2])/2, '#c9ccd0', 6);
    avLights(g, [[(R0[0] + R1[0])/2, ridge + 8.3, (R0[2] + R1[2])/2]], 0.5);
    return X.done(); }};
place('hkvcosco');

