// ===================================================================================================================
// WAN CHAI NORTH (Harbour Road / Gloucester Road / the HKCEC phase 1 block)
// ===================================================================================================================
// HKCEC phase 1 (1988) on the Wan Chai reclamation: the Old Wing exhibition podium (OSM w26490161, 32 m) - beige horizontal bands
// with dark glass, a white steel arched truss over the harbour-side hall - and the four towers standing on it (OSM parts, base 31 m):
// Convention Plaza Office Tower (181 m), silver-grey glass in stepped tiers with banded corners; Convention Plaza Apartments (164 m),
// dark blue glass striped by white mullion pairs; the Renaissance Harbour View (150 m, blue glass) and the Grand Hyatt (129 m, pale
// grey with horizontal bands of windows) hotels (photos 0010, 0011, 0012). At night the Old Wing's harbour front carries outline LED frames and a colour band (Symphony of Lights), the office
// tower's crown is lit and its roof sends searchlights.
LANDMARKS.hkvconvplaza = {zh:'会展广场', en:'Convention Plaza', cat:'new', r:118, h:181,
  lt:{m:1, c:'#eaf0ff', k:0.65, anim:'show', c2:'#7fd8ff'},
  build(){
    const k = 'hkvconvplaza', OW = clean(FD[k].ow), X = mk(k, OW), g = X.g, B = X.B;
    // the Old Wing podium
    foot(B, OW, X.gr, 0.3, 6);
    prismP(B.p('#d6ccb6'), OW, 6, 32); bandsP(B.p({c:'#3d474d', glow:'#ffe0b4', gk:0.5}), OW, 9, 30, 6.2, 3.4, 0.1);
    bandsP(B.p('#eeeeea'), OW, 12.8, 31, 6.2, 0.7, 0.35); edgeP(B.p('#eeeeea'), OW, 32, 0.5, 1.4, 0.05);
    { // the harbour-side arched truss (white) and the LED outline frames on the harbour face
      const i = edgeTo(OW, 0), a = OW[i], b = OW[(i+1) % OW.length], [nx, nz] = outN(OW, i), L = Math.hypot(b[0]-a[0], b[1]-a[1]), ux = (b[0]-a[0])/L, uz = (b[1]-a[1])/L;
      const T = B.p('#eeeeea'), s0 = L*0.55, s1 = L*0.92, n = 14, pts = [];
      for (let j = 0; j <= n; j++){ const t = j/n, s = s0 + (s1 - s0)*t, y = 32 + 13*Math.sin(t*PI), x = a[0] + ux*s - nx*14, z = a[1] + uz*s - nz*14; pts.push([x, y, z]); }
      for (let j = 0; j < n; j++){ segP(T, pts[j], pts[j+1], 0.5, 4); const q = pts[j]; segP(T, q, [q[0] - nx*18, 32, q[2] - nz*18], 0.28, 3); segP(T, q, [q[0] + nx*3, 32, q[2] + nz*3], 0.28, 3); }
      const LE = B.p(ledMat({c:'#e4dce9', ds:true}, 'magenta', 'cecled'));
      for (const y of [8.5, 30.5]) { const A = [a[0] + nx*0.5, y, a[1] + nz*0.5], Bq = [b[0] + nx*0.5, y, b[1] + nz*0.5]; quadP(LE, A, Bq, [Bq[0], y + 0.6, Bq[2]], [A[0], y + 0.6, A[2]]); }
      for (let j = 0; j <= 8; j++){ const s = L*j/8, x = a[0] + ux*s + nx*0.5, z = a[1] + uz*s + nz*0.5; quadP(LE, [x - ux*0.3, 8.5, z - uz*0.3], [x + ux*0.3, 8.5, z + uz*0.3], [x + ux*0.3, 31, z + uz*0.3], [x - ux*0.3, 31, z - uz*0.3]); }
    }
    // the office tower: three tiers, the corners cut deeper at each step
    { const P0 = clean(FD[k].cpo), RR = rectOf(P0), hu = (RR.u1 - RR.u0)/2, C0 = hu + RR.hw;
      const o = {g:{c:'#8f9aa3', m:1, fh:3.8, cw:3.0}, m:'#d3d9dd', sp:1.5, mw:0.12, b:'#c9cbc7', fh:3.8, bh:0.55};
      const T1 = chamfer(P0, RR.f, C0 - 3), T2 = chamfer(P0, RR.f, C0 - 9), T3 = chamfer(P0, RR.f, C0 - 15);
      piece(B, T1, 32, 118, o); edgeP(B.p('#d3d9dd'), T1, 118, 0.5, 1.2, 0.05);
      piece(B, T2, 32, 152, o); edgeP(B.p('#d3d9dd'), T2, 152, 0.5, 1.2, 0.05);
      piece(B, T3, 32, 175, o);
      prismP(B.p({c:'#c7cfd5', m:0, lc:'#eaf2ff', lk:1.2}), T3, 175, 181); roofTop(B, offP(T3, 1.5), 181, {plh:3.5, pc:'#d3d9dd', plc:'#c9cbc7'});
      const c = cenP(T3); lamps(g, [[c[0] - 5, 185, c[1]], [c[0] + 5, 185, c[1]], [c[0], 185, c[1] - 4]]); avLights(g, [[c[0], 184.8, c[1] + 4]], 0.45); }
    // apartments and hotels (OSM parts: the higher block and the lower wing of each)
    const hotel = (PS, wall, win, cap) => { for (const [b, t, R] of PS){ const Q = clean(R); if (Q.length < 3) continue;
      piece(B, Q, Math.max(31, b), t - 3, {w:wall, strip:win, fh:3.2, sy:1.0, sh:1.55});
      prismP(B.p(cap), Q, t - 3, t); edgeP(B.p(cap), Q, t, 0.4, 1.2, 0.05); } };
    const HW = {c:'#4a5358', m:1, fh:3.2, cw:2.4};
    // the apartments (photo 0012: dark blue glass striped by white vertical mullion pairs) and the Renaissance (blue glass) ...
    const blueT = (PS, gl) => { for (const [b, t, R] of PS){ const Q = clean(R); if (Q.length < 3) continue;
      piece(B, Q, Math.max(31, b), t - 3, {g:gl, m:'#d3d9dd', sp:4.2, mw:0.45, b:'#c9cbc7', fh:9.6, bh:0.5}); prismP(B.p('#c9cbc7'), Q, t - 3, t); edgeP(B.p('#c9cbc7'), Q, t, 0.4, 1.2, 0.05); } };
    blueT(FD[k].cpap, {c:'#2d4a6e', m:1, fh:3.2, cw:2.4}); blueT(FD[k].renp, {c:'#4c739a', m:1, fh:3.3, cw:2.6});
    // ... and the Grand Hyatt (pale banded)
    hotel(FD[k].ghp, '#dfe0dc', HW, '#c9cbc7');
    return X.done(); }};
place('hkvconvplaza');

