// silver-blue glass with white vertical fins and lit crown screens; Dorset House (151 m) and PCCW Tower (163 m - OSM), the twin
// octagonal towers of deep blue mirror glass; Oxford House (165 m; the tower outline OSM w100652768, inside the older outline w296724527), Lincoln House (106 m) and Berkshire
// House (137 m) in blue glass.
const TKP = {
  NEW:{g:{c:'#93a8b8', m:1, fh:4.2, cw:3.0}, m:'#e6eaec', sp:1.5, mw:0.15, p:'#f2f3f1', psp:3.0, pw:0.25, pd:0.7, b:'#6f8494', fh:4.2, bh:0.5},
  BLU:{g:{c:'#27476b', m:1, fh:3.8, cw:3.0}, m:'#6c8aa8', sp:1.6, mw:0.12, b:'#1d3654', fh:3.8, bh:0.5},
  MBL:{g:{c:'#45698c', m:1, fh:3.8, cw:3.0}, m:'#9bb2c6', sp:1.6, mw:0.12, b:'#34536f', fh:3.8, bh:0.5}};
function tkTower(key, zh, en, H, sty, crown, r, extra){
  LANDMARKS[key] = {zh, en, cat:'new', r, h:H, label:extra && extra.label, lt:{m:1, c:'#e6f0ff', k:0.65},
    build(){
      const P = clean(FD[key].t), X = mk(key, P), g = X.g, B = X.B, o = TKP[sty], c = cenP(P);
      foot(B, P, X.gr, 0.3, 8);
      if (sty === 'BLU'){ // octagonal tower, stepped crown
        piece(B, P, 8, H - 18, o); const Q1 = scaleP(P, c, 0.82), Q2 = scaleP(P, c, 0.6);
        prismP(B.p(o.g), Q1, H - 18, H - 8); edgeP(B.p('#9bb2c6'), P, H - 18, 0.4, 1.1, 0.05); prismP(B.p('#6c8aa8'), Q2, H - 8, H); edgeP(B.p('#9bb2c6'), Q1, H - 8, 0.4, 1.1, 0.05);
        avLights(g, [[c[0], H + 0.6, c[1]]], 0.5);
      } else {
        piece(B, P, 8, H - crown, o);
        if (crown > 6){ prismP(B.p({c:'#e3e8eb', m:0, lc:'#e6f0ff', lk:1.15}), P, H - crown, H, true); mullP(B.p('#f2f3f1'), P, H - crown, H, 1.4, 0.3, 0.1, 0.5); flatP(B.p('#8e9395'), offP(P, 1.5), H - crown + 2); avCorners(g, P, H + 0.5, 2); }
        else { prismP(B.p('#3a4c5e'), P, H - crown, H); roofTop(B, offP(P, 0.8), H, {plh:3}); }
      }
      if (extra && extra.pod){ const Q = clean(FD[key].pod); foot(B, Q, X.gr, 0.3, 4); prismP(B.p('#c9ccc9'), Q, 4, 10); edgeP(B.p('#b9bcb9'), Q, 10, 0.4, 1.0, 0.05); }
      return X.done(); }};
  place(key);
}
