// ===================================================================================================================
// SYMPHONY OF LIGHTS (A Symphony of Lights, nightly 20:00): searchlight fans and green lasers from the harbour-front roofs, as seen in
// photos 0036-0038 and 0049 - white fans from Two IFC, Jardine House and Exchange Square, the Bank of China Tower and two Admiralty
// roofs (one magenta), Central Plaza, Convention Plaza and Sun Hung Kai Centre (blue), green lasers from Central Plaza, Convention
// Plaza, Sun Hung Kai Centre and the HKCEC. Beams are additive light only: invisible by day and outside the show (they follow the
// app's light-show schedule LMS.show, so they appear around 20:00 and 21:00), pulsing in sequence. Two keys without footprint
// (anchored on the water, nothing hidden), no labels.
function solBeams(key, zh, en){
  LANDMARKS[key] = {zh, en, cat:'new', r:20, h:60, label:false, lt:{m:0, c:'#ffffff', k:0},
    build(){
      const g = new THREE.Group(), R = FD[key].roofs, rng = LMCTX.rng, pos = [], col = [];
      const COL = {w:[1, 0.97, 0.92], m:[1, 0.3, 0.85], b:[0.45, 0.65, 1], g:[0.25, 1, 0.35]};
      let id = 0;
      for (const [x, y, z, n, c, kind] of R){
        const laser = kind === 'laser';
        for (let i = 0; i < n; i++, id++){
          const az = (laser ? -25 + 50*(i + 0.5)/n : -55 + 110*(i + 0.5)/n) + (rng() - 0.5)*8, el = laser ? 6 + rng()*10 : 48 + rng()*30, L = laser ? 900 : 420;
          const a = az*PI/180, e = el*PI/180, d = [Math.sin(a)*Math.cos(e), Math.sin(e), -Math.cos(a)*Math.cos(e)];
          const up = Math.abs(d[1]) < 0.95 ? [0, 1, 0] : [1, 0, 0];
          let u = [d[1]*up[2] - d[2]*up[1], d[2]*up[0] - d[0]*up[2], d[0]*up[1] - d[1]*up[0]]; const ul = Math.hypot(...u); u = u.map(q => q/ul);
          const v = [d[1]*u[2] - d[2]*u[1], d[2]*u[0] - d[0]*u[2], d[0]*u[1] - d[1]*u[0]];
          const r0 = laser ? 0.25 : 0.7, r1 = laser ? 0.9 : 11, ph = (id*0.137) % 1, cc = COL[c] || COL.w;
          const ring = (t, r) => { const o = []; for (let k = 0; k < 4; k++){ const q = k/4*TAU; o.push([x + d[0]*L*t + (u[0]*Math.cos(q) + v[0]*Math.sin(q))*r, y + d[1]*L*t + (u[1]*Math.cos(q) + v[1]*Math.sin(q))*r, z + d[2]*L*t + (u[2]*Math.cos(q) + v[2]*Math.sin(q))*r]); } return o; };
          const A = ring(0, r0), Bq = ring(1, r1), fa = laser ? 0.9 : 1.0, fb = laser ? 0.5 : 0.0;
          for (let k = 0; k < 4; k++){ const j = (k + 1) % 4;
            for (const [p, f] of [[A[k], fa], [A[j], fa], [Bq[j], fb], [A[k], fa], [Bq[j], fb], [Bq[k], fb]]){ pos.push(...p); col.push(cc[0]*f, cc[1]*f, cc[2]*f); } }
        }
      }
      const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
      const spec = {c:'#fffffe', vc:true, ds:true}, m = lmMat(spec);
      if (!m.userData.sol){ m.userData.sol = 1; m.transparent = true; m.depthWrite = false; m.blending = THREE.AdditiveBlending; m.fog = false;
        const base = m.onBeforeCompile;
        m.onBeforeCompile = function solBeam(sh){ base(sh);
          sh.uniforms.uSoL = (typeof LMS !== 'undefined' && LMS.show) || {value:1};
          sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vSP;').replace('#include <begin_vertex>', '#include <begin_vertex>\nvSP = transformed;');
          sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vSP;\nuniform float uSoL;')
            .replace('#include <dithering_fragment>', '#include <dithering_fragment>\n{ float kS = clamp((uSoL - 0.45)/0.35, 0.0, 1.0)*uNight; float pu = 0.55 + 0.45*sin(uTime*0.8 + vSP.x*0.013 + vSP.z*0.017); gl_FragColor = vec4(vColor*kS*pu*0.45, 1.0); }');
        };
        m.customProgramCacheKey = () => 'hkvsol1';
      }
      const mesh = new THREE.Mesh(geo, m); mesh.renderOrder = 6; g.add(mesh);
      LBox(g, 0.3, 0.3, 0.3, 0, -3, 0, '#1d2a33');   // a speck under the water: gives the app's hiding hull a point (hides nothing)
      return g; }};
  place(key);
}
