// ===================================================================================================================
// FRONTAGE FIXES: low harbour-front structures whose OSM outlines carry no height or levels, so the app extruded them to the
// estimated height of a tower (50-130 m phantom blocks in the skyline). Rebuilt at their real scale. Heights are estimates (the
// OSM tags give none): canopy roofs (building=roof) ~6 m, the covered pier walkway ~11 m, ventilation buildings / substations
// ~16-24 m, the fire station ~16 m. No labels (label:false).
// ===================================================================================================================
function lowFix(key, zh, en, list, r){
  LANDMARKS[key] = {zh, en, cat:'new', r, h:Math.max(...list.map(q => q[1])), label:false, lt:{m:1, c:'#ffe4c0', k:0.45},
    build(){
      const P0 = clean(FD[key][list[0][0]]), X = mk(key, P0), g = X.g, B = X.B;
      for (const [n, H, sty] of list){ const P = clean(FD[key][n]); if (P.length < 3) continue;
        if (sty === 'canopy'){ // a thin roof on slim posts
          const c = cenP(P); flatP(B.p('#d9dbd8'), P, H); flatP(B.p('#d9dbd8'), P, H - 0.5); edgeP(B.p('#c4c7c4'), P, H - 0.5, 0.3, 0.5, 0.05);
          for (const p of P){ const q = [p[0] + (c[0] - p[0])*0.06, p[1] + (c[1] - p[1])*0.06]; segP(B.p('#9a9e9c'), [q[0], X.gr(q[0], q[1]) - 1, q[1]], [q[0], H - 0.5, q[1]], 0.18, 4); }
          LBoxD(g, 0.1, 0.1, 0.1, c[0], 0.3, c[1], '#9a9e9c');   // keeps a low vertex at the centre for the hiding hull
        } else if (sty === 'walk'){ // covered pier walkway: deck on columns, glazed sides, green-edged roof
          foot(B, P, X.gr, 0.3, 0); prismP(B.p({c:'#4a555a', glow:'#ffe6c0', gk:0.5}), offP(P, 0.4), 6, H - 1.2, true); flatP(B.p('#cfd2cf'), P, 6);
          prismP(B.p('#e4e5e1'), P, H - 1.2, H); edgeP(B.p('#3f7d5a'), P, H - 0.6, 0.3, 0.8, 0.08);
          mullP(B.p('#d6d8d4'), P, 0.3, 6, 7, 0.6, -0.5, 0.6);
        } else { // service block: louvred walls, plain parapet
          foot(B, P, X.gr, 0.3, 0); prismP(B.p(sty === 'civic' ? '#d8d2c4' : '#b9bdb8'), P, 0.3, H);
          bandsP(B.p(sty === 'civic' ? {c:'#434b50', m:1, fh:3.6, cw:2.6} : '#8c918e'), P, 3, H - 1.5, sty === 'civic' ? 3.6 : 1.2, sty === 'civic' ? 1.6 : 0.5, 0.08);
          edgeP(B.p('#d3d6d2'), P, H, 0.35, 1.1, 0.05);
        } }
      return X.done(); }};
  place(key);
}
